func (l *PQLLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 47:
		return l.FILTER_KW_FROM_Sempred(localctx, predIndex)

	case 48:
		return l.FILTER_KW_FILTER_Sempred(localctx, predIndex)

	case 49:
		return l.FILTER_KW_DERIVE_Sempred(localctx, predIndex)

	case 50:
		return l.FILTER_KW_SELECT_Sempred(localctx, predIndex)

	case 51:
		return l.FILTER_KW_GROUP_Sempred(localctx, predIndex)

	case 52:
		return l.FILTER_KW_JOIN_Sempred(localctx, predIndex)

	case 53:
		return l.FILTER_KW_ARRAY_JOIN_Sempred(localctx, predIndex)

	case 54:
		return l.FILTER_KW_SORT_Sempred(localctx, predIndex)

	case 55:
		return l.FILTER_KW_TAKE_Sempred(localctx, predIndex)

	case 56:
		return l.FILTER_KW_SKIP_Sempred(localctx, predIndex)

	case 57:
		return l.FILTER_KW_WINDOW_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

func (p *PQLLexer) FILTER_KW_FROM_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	switch predIndex {
	case 0:
		return p.GetCharPositionInLine() == 0

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}

